  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 4px;
  padding: 4px;
  background: rgba(9, 13, 22, 0.6);
  border: 1px solid var(--line);
  border-radius: 12px;
}

