  appearance: none;
  border: 0;
  border-radius: 9px;
  padding: 8px 6px;
  font-size: 13px;
  color: var(--muted);
  background: transparent;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
  font-family: inherit;
