  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #111;
  box-shadow: inset -2px -3px 5px rgba(255, 255, 255, 0.18), 0 2px 5px rgba(0, 0, 0, 0.5);
  flex: none;
}
.stone-dot.white { background: #f4f4f4; box-shadow: inset -2px -3px 5px rgba(0, 0, 0, 0.18), 0 2px 5px rgba(0, 0, 0, 0.4); }

.thinking {
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 500;
  color: var(--accent);
}
.thinking.hidden { display: none; }

.spinner {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid rgba(79, 140, 255, 0.28);
  border-top-color: var(--accent);
  animation: spin 0.8s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.stat {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 8px 10px;
  border-radius: 11px;
  background: rgba(9, 13, 22, 0.5);
  border: 1px solid var(--line);
}
.stat span { font-size: 11.5px; color: var(--muted); }
.stat b { font-size: 16px; font-variant-numeric: tabular-nums; }

