  background: linear-gradient(180deg, #1c2740, #131b2b);
  border: 1px solid var(--line);
  border-radius: 20px;
  padding: 26px 26px 22px;
  text-align: center;
  box-shadow: var(--shadow);
}
.modal-card.wide { width: min(560px, 100%); text-align: left; }
.modal-card h2 { margin: 8px 0 6px; font-size: 22px; }
.modal-card p { margin: 6px 0; font-size: 13.5px; line-height: 1.7; }
