  overflow-x: auto;
}
.modal-card code {
  background: rgba(9, 13, 22, 0.75);
  padding: 1px 6px;
  border-radius: 6px;
  font-size: 12.5px;
}
.muted { color: var(--muted); }

.result-icon { font-size: 44px; line-height: 1; }
.result-icon.black { color: #0d0d0d; text-shadow: 0 0 1px #888, 0 0 12px rgba(255, 255, 255, 0.25); }
.result-icon.white { color: #f2f2f2; }
.result-icon.draw { color: #9aa7c4; }

.result-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 18px 0 20px; }
.modal-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }

.replay-bar {
  position: fixed;
  left: 50%;
  bottom: 18px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 14px;
  border-radius: 15px;
  background: rgba(20, 28, 46, 0.97);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  z-index: 60;
  max-width: 94vw;
}
.replay-bar.hidden { display: none; }
.replay-bar input[type="range"] { width: 220px; accent-color: var(--accent); }
.rp-info { font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; min-width: 68px; text-align: center; }

@media (max-width: 980px) {
  .layout { grid-template-columns: 1fr; }
  .side { order: 2; }
  .replay-bar { flex-wrap: wrap; justify-content: center; }
  .replay-bar input[type="range"] { width: 40vw; }
}

@media (max-width: 520px) {
  .app { padding: 14px 12px 30px; }
  .brand-text p { display: none; }
  .stats { grid-template-columns: 1fr 1fr; }
}

