import { BOARD_SIZE, EMPTY, WALL } from './config.js';

export class Board {
  constructor(size = BOARD_SIZE) {
    this.size = size;
    this.cells = new Int8Array(size * size);
    this.count = 0;
  }

  index(x, y) {
    return y * this.size + x;
  }

  inBounds(x, y) {
    return x >= 0 && y >= 0 && x < this.size && y < this.size;
  }

  get(x, y) {
    return this.inBounds(x, y) ? this.cells[y * this.size + x] : WALL;
  }

  isFree(x, y) {
    return this.inBounds(x, y) && this.cells[y * this.size + x] === EMPTY;
  }

  place(x, y, color) {
    if (!this.inBounds(x, y)) return false;
    const i = y * this.size + x;
    if (this.cells[i] !== EMPTY) return false;
    this.cells[i] = color;
    this.count++;
    return true;
  }

  remove(x, y) {
    if (!this.inBounds(x, y)) return false;
    const i = y * this.size + x;
    if (this.cells[i] === EMPTY) return false;
    this.cells[i] = EMPTY;
    this.count--;
    return true;
  }

  reset() {
    this.cells.fill(EMPTY);
    this.count = 0;
  }

  get filled() {
    return this.count >= this.size * this.size;
  }
}

export const BOARD_SIZE = 15;

export const EMPTY = 0;
export const BLACK = 1;
export const WHITE = 2;
export const WALL = 3;

export const RESULT = {
  NONE: 0,
  BLACK: 1,
  WHITE: 2,
  DRAW: 3,
};

export const MODE = {
  PVE: 'pve',
  PVP: 'pvp',
};

export const DIFFICULTY = {
  EASY: 'easy',
  NORMAL: 'normal',
  HARD: 'hard',
};

export const HUMAN_COLOR = BLACK;
export const AI_COLOR = WHITE;

export const STORAGE = {
  CURRENT: 'gomoku.current.v1',
  HISTORY: 'gomoku.history.v1',
  SETTINGS: 'gomoku.settings.v1',
};

export const HISTORY_LIMIT = 12;

export const AI_THINK_LIMIT_MS = 2000;

export const DIFFICULTY_LABEL = {
  [DIFFICULTY.EASY]: '简单',
  [DIFFICULTY.NORMAL]: '普通',
  [DIFFICULTY.HARD]: '困难',
};

export const MODE_LABEL = {
  [MODE.PVE]: '人机对战',
  [MODE.PVP]: '双人对战',
};

export function otherColor(color) {
  return color === BLACK ? WHITE : BLACK;
}

export function colorLabel(color) {
  if (color === BLACK) return '黑方';
  if (color === WHITE) return '白方';
  return '平局';
}

import { EMPTY, WALL } from './config.js';

export const DIRECTIONS = [
  [1, 0],
  [0, 1],
  [1, 1],
  [1, -1],
];

export function collectLine(board, x, y) {
  const color = board.get(x, y);
  if (color === EMPTY || color === WALL) return null;

  for (let d = 0; d < DIRECTIONS.length; d++) {
    const dx = DIRECTIONS[d][0];
    const dy = DIRECTIONS[d][1];
    const cells = [board.index(x, y)];

    let cx = x - dx;
    let cy = y - dy;
    while (board.get(cx, cy) === color) {
      cells.unshift(board.index(cx, cy));
      cx -= dx;
      cy -= dy;
    }

    cx = x + dx;
    cy = y + dy;
    while (board.get(cx, cy) === color) {
      cells.push(board.index(cx, cy));
      cx += dx;
      cy += dy;
    }

    if (cells.length >= 5) return { cells, dx, dy, color };
  }

  return null;
}

export function isWinningMove(board, x, y) {
  return collectLine(board, x, y) !== null;
}

export class Clock {
  constructor(autoStart = false) {
    this._accum = 0;
    this._since = 0;
    this._running = false;
    if (autoStart) this.start();
  }

  start() {
    if (this._running) return;
    this._running = true;
    this._since = performance.now();
  }

  pause() {
    if (!this._running) return;
    this._accum += performance.now() - this._since;
    this._running = false;
  }

  reset() {
    this._accum = 0;
    this._since = performance.now();
  }

  setElapsed(ms) {
    this._accum = Math.max(0, Number(ms) || 0);
    this._since = performance.now();
  }

  get elapsed() {
    return this._accum + (this._running ? performance.now() - this._since : 0);
  }

  get running() {
    return this._running;
  }

  format() {
    return Clock.format(this.elapsed);
  }

  static format(ms) {
    const total = Math.max(0, Math.floor(ms / 1000));
    const minutes = Math.floor(total / 60);
    const seconds = total % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  }
}

