+export function matchPatterns(str) {
+  let score = 0;
+  let work = str;
+
+  for (let g = 0; g < GROUPS.length; g++) {
+    const group = GROUPS[g];
+    for (let p = 0; p < group.patterns.length; p++) {
+      const pattern = group.patterns[p];
+      let from = 0;
