import { readdirSync, copyFileSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import path from 'node:path';

const dir = '.tmp-smoke';
rmSync(dir, { recursive: true, force: true });
mkdirSync(path.join(dir, 'src'), { recursive: true });
writeFileSync(path.join(dir, 'package.json'), '{"type":"module"}');
for (const f of readdirSync('src')) {
  if (f.endsWith('.js')) copyFileSync(path.join('src', f), path.join(dir, 'src', f));
}

class ClassList {
  constructor() {
    this.set = new Set();
  }
  add(...c) {
    c.forEach((x) => this.set.add(x));
  }
  remove(...c) {
    c.forEach((x) => this.set.delete(x));
  }
  toggle(c, force) {
    if (force === undefined) this.set.has(c) ? this.set.delete(c) : this.set.add(c);
    else if (force) this.set.add(c);
    else this.set.delete(c);
  }
  contains(c) {
    return this.set.has(c);
  }
}

const gradient = { addColorStop() {} };
const ctx = new Proxy(
  {},
  {
    get(target, prop) {
      if (prop in target) return target[prop];
      return (...args) => (String(prop).startsWith('create') ? gradient : undefined);
    },
    set(target, prop, value) {
      target[prop] = value;
      return true;
    },
  }
);

let created = 0;
class El {
  constructor(tag) {
    this.tagName = tag;
    this.children = [];
    this.dataset = {};
    this.classList = new ClassList();
    this.style = {};
    this._listeners = {};
    this._text = '';
    this.value = '0';
    this.max = '0';
    this.disabled = false;
    this.checked = false;
    this.className = '';
    this.clientWidth = 640;
  }
  set textContent(v) {
    this._text = String(v);
    if (v === '') this.children = [];
  }
  get textContent() {
    return this._text;
  }
  appendChild(child) {
    this.children.push(child);
    return child;
  }
  addEventListener(type, fn) {
    (this._listeners[type] = this._listeners[type] || []).push(fn);
  }
  removeEventListener() {}
  querySelectorAll() {
    return [];
  }
  querySelector() {
    return null;
  }
  closest() {
    return null;
  }
  dispatch(type, event) {
    (this._listeners[type] || []).forEach((fn) => fn(event));
  }
  getBoundingClientRect() {
    return { left: 0, top: 0, width: 616, height: 616 };
  }
  getContext() {
    return ctx;
  }
}

const els = new Map();
function el(id) {
  if (!els.has(id)) {
    const e = new El('div');
    e.clientWidth = 640;
    els.set(id, e);
  }
  return els.get(id);
}

const canvas = el('board');
const frame = new El('div');
frame.clientWidth = 640;
canvas.parentElement = frame;

const store = new Map();
globalThis.localStorage = {
  getItem: (k) => (store.has(k) ? store.get(k) : null),
  setItem: (k, v) => store.set(k, String(v)),
  removeItem: (k) => store.delete(k),
};
globalThis.document = {
  hidden: false,
  getElementById: (id) => el(id),
  querySelector: (sel) => (sel === '.stats' ? el('__stats') : null),
  createElement: (tag) => new El(tag),
  addEventListener() {},
  removeEventListener() {},
};
