  setTimeout,
  clearTimeout,
  setInterval,
  clearInterval,
  confirm: () => true,
};

const load = (name) => import(pathToFileURL(path.resolve(dir, 'src', name)).href);
let pass = 0;
let fail = 0;
function check(name, cond, extra = '') {
  if (cond) {
    pass++;
    console.log('PASS ' + name);
  } else {
    fail++;
    console.log('FAIL ' + name + (extra ? ' :: ' + extra : ''));
  }
}
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
async function waitFor(fn, timeout = 6000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    if (fn()) return true;
    await wait(25);
  }
  return false;
}

const { UI } = await load('ui.js');
const ui = new UI();
ui.start();
check('UI boots without throwing', true);
check('canvas click listener bound', (canvas._listeners.click || []).length === 1);

// click the centre intersection -> human move + AI reply
canvas.dispatch('click', { clientX: 308, clientY: 308 });
check('click placed a stone', ui.game.moves.length === 1);
const replied = await waitFor(() => ui.game.moves.length === 2 && ui.game.status === 'playing', 6000);
check('AI replied after human click', replied, `moves=${ui.game.moves.length}`);
check('move counter rendered', el('stat-moves').textContent === '2', el('stat-moves').textContent);
check('thinking indicator hidden after reply', el('thinking').classList.contains('hidden'));

// clicking an occupied point is rejected with a toast
canvas.dispatch('click', { clientX: 308, clientY: 308 });
check('occupied point rejected', ui.game.moves.length === 2);
check('toast shown', el('toast').classList.contains('show'), el('toast').textContent);

// clicking far outside the board is rejected
canvas.dispatch('click', { clientX: 5000, clientY: 5000 });
check('off-board click rejected', ui.game.moves.length === 2);

// replay of a stored finished game
store.set(
  'gomoku.history.v1',
  JSON.stringify([
    {
      id: 'g1',
      endedAt: Date.now(),
      mode: 'pvp',
      difficulty: 'normal',
      winner: 1,
      moveCount: 9,
      durationMs: 60000,
      moves: [[3, 7], [3, 0], [4, 7], [4, 0], [5, 7], [5, 0], [6, 7], [6, 0], [7, 7]],
    },
  ])
);
ui.renderHistory();
check('history list rendered', el('history-list').children.length === 1);

const entry = JSON.parse(store.get('gomoku.history.v1'))[0];
ui.enterReplay(entry);
check('replay bar visible', !el('replay-bar').classList.contains('hidden'));
check('replay starts at last move', ui.replay.index === 9, String(ui.replay.index));
check('replay board rebuilt', ui.replay.board.get(7, 7) === 1 && ui.replay.board.get(6, 0) === 2);
ui.stepReplay(-1);
check('replay step back works', ui.replay.index === 8);
check('replay info rendered', el('rp-info').textContent === '8 / 9', el('rp-info').textContent);
ui.gotoReplay(0);
check('replay to start empties board', ui.replay.board.count === 0);
ui.exitReplay();
check('exit replay hides bar', el('replay-bar').classList.contains('hidden'));

// finish a PvP game and confirm the result modal
ui.game.newGame({ mode: 'pvp' });
const black = [[1, 1], [2, 1], [3, 1], [4, 1], [5, 1]];
const white = [[1, 9], [2, 9], [3, 9], [4, 9]];
for (let i = 0; i < 5; i++) {
  ui.game.tryPlace(black[i][0], black[i][1]);
  if (i < 4) ui.game.tryPlace(white[i][0], white[i][1]);
}
check('game finished', ui.game.status === 'over' && ui.game.winner === 1);
check('result modal shown', !el('modal').classList.contains('hidden'));
check('result title set', el('result-title').textContent.includes('获胜'), el('result-title').textContent);
check('result move count set', el('result-moves').textContent === '9', el('result-moves').textContent);
check('finished game added to history', JSON.parse(store.get('gomoku.history.v1')).length === 2);

ui.game.undo();
check('undo after finish resumes play', ui.game.status === 'playing');

console.log(`\n${pass} passed, ${fail} failed`);
rmSync(dir, { recursive: true, force: true });
process.exit(fail ? 1 : 0);

